pub async fn me_delete_github_connection(
    State(state): State<Arc<AppState>>,
    session: Session,
    Path(connection_id): Path<String>,
) -> Result<Json<MeGitHubConnectionsResponse>, ApiError> {
    let user_id = require_active_user_id(state.as_ref(), &session).await?;
    let connection_id = parse_local_id_param(connection_id, "connection_id")?;

    let exists = sqlx::query_scalar::<_, i64>(
        r#"
        SELECT COUNT(*)
        FROM github_connections
        WHERE id = ?
          AND user_id = ?
        "#,
    )
    .bind(connection_id.as_str())
    .bind(user_id.as_str())
    .fetch_one(&state.pool)
    .await
    .map_err(ApiError::internal)?;
    if exists == 0 {
        return Err(ApiError::new(
            StatusCode::NOT_FOUND,
            "github_connection_not_found",
            "github connection not found",
        ));
    }

    let total = sqlx::query_scalar::<_, i64>(
        r#"
        SELECT COUNT(*)
        FROM github_connections
        WHERE user_id = ?
        "#,
    )
    .bind(user_id.as_str())
    .fetch_one(&state.pool)
    .await
    .map_err(ApiError::internal)?;
    if total <= 1 {
        return Err(ApiError::new(
            StatusCode::CONFLICT,
            "last_github_connection_guard",
            "at least one github connection is required",
        ));
    }

    let (writer, mut tx) = state
        .sqlite_writer
        .begin_immediate_with_priority(
            &state.pool,
            "github_connection_unlink",
            crate::sqlite_write::SqliteWritePriority::Foreground,
        )
        .await
        .map_err(ApiError::internal)?;
    sqlx::query(
        r#"
        DELETE FROM github_connections
        WHERE id = ?
          AND user_id = ?
        "#,
    )
    .bind(connection_id.as_str())
    .bind(user_id.as_str())
    .execute(&mut *tx)
    .await
    .map_err(ApiError::internal)?;

    sqlx::query(
        r#"
        DELETE FROM reaction_pat_tokens
        WHERE user_id = ?
          AND owner_github_connection_id = ?
        "#,
    )
    .bind(user_id.as_str())
    .bind(connection_id.as_str())
    .execute(&mut *tx)
    .await
    .map_err(ApiError::internal)?;

    tx.commit().await.map_err(ApiError::internal)?;
    drop(writer);

    me_get_github_connections(State(state), session).await
}

pub async fn me_delete_passkey(
    State(state): State<Arc<AppState>>,
    session: Session,
    Path(passkey_id): Path<String>,
) -> Result<Json<MePasskeysResponse>, ApiError> {
    let user_id = require_active_user_id(state.as_ref(), &session).await?;
    let passkey_id = parse_local_id_param(passkey_id, "passkey_id")?;

    let exists = sqlx::query_scalar::<_, i64>(
        r#"
        SELECT COUNT(*)
        FROM user_passkeys
        WHERE id = ?
          AND user_id = ?
        "#,
    )
    .bind(passkey_id.as_str())
    .bind(user_id.as_str())
    .fetch_one(&state.pool)
    .await
    .map_err(ApiError::internal)?;
    if exists == 0 {
        return Err(ApiError::new(
            StatusCode::NOT_FOUND,
            "passkey_not_found",
            "passkey not found",
        ));
    }

    let (writer, mut tx) = state
        .sqlite_writer
        .begin_immediate_with_priority(
            &state.pool,
            "passkey_delete",
            crate::sqlite_write::SqliteWritePriority::Foreground,
        )
        .await
        .map_err(ApiError::internal)?;
    sqlx::query(
        r#"
        DELETE FROM user_passkeys
        WHERE id = ?
          AND user_id = ?
        "#,
    )
    .bind(passkey_id.as_str())
    .bind(user_id.as_str())
    .execute(&mut *tx)
    .await
    .map_err(ApiError::internal)?;

    let remaining = sqlx::query_scalar::<_, i64>(
        r#"
        SELECT COUNT(*)
        FROM user_passkeys
        WHERE user_id = ?
        "#,
    )
    .bind(user_id.as_str())
    .fetch_one(&mut *tx)
    .await
    .map_err(ApiError::internal)?;

    if remaining == 0 {
        sqlx::query(
            r#"
            UPDATE users
            SET passkey_user_handle_uuid = NULL, updated_at = ?
            WHERE id = ?
            "#,
        )
        .bind(chrono::Utc::now().to_rfc3339())
        .bind(user_id.as_str())
        .execute(&mut *tx)
        .await
        .map_err(ApiError::internal)?;
    }

    tx.commit().await.map_err(ApiError::internal)?;
    drop(writer);

    me_get_passkeys(State(state), session).await
}

