const BRIEF_PREVIEW_MARKDOWN_MAX_CHARS: usize = 600;

fn brief_preview_markdown(content_markdown: &str) -> String {
    content_markdown
        .chars()
        .take(BRIEF_PREVIEW_MARKDOWN_MAX_CHARS)
        .collect()
}

fn brief_markdown_has_section(markdown: &str, heading: &str) -> bool {
    markdown.lines().any(|line| line.trim() == heading)
}

#[derive(Debug, Serialize, sqlx::FromRow)]
pub struct BriefSummaryItem {
    id: String,
    date: String,
    window_start: Option<String>,
    window_end: Option<String>,
    effective_time_zone: Option<String>,
    effective_local_boundary: Option<String>,
    release_count: usize,
    release_ids: Vec<String>,
    preview_markdown: String,
    covers_repo_stars: bool,
    covers_followers: bool,
    created_at: String,
    updated_at: String,
}

pub async fn list_briefs(
    State(state): State<Arc<AppState>>,
    session: Session,
    headers: HeaderMap,
) -> Result<Json<Vec<BriefSummaryItem>>, ApiError> {
    let user_id = require_business_user_id(state.as_ref(), &session, &headers).await?;

    #[derive(Debug, sqlx::FromRow)]
    struct BriefRow {
        id: String,
        date: String,
        window_start_utc: Option<String>,
        window_end_utc: Option<String>,
        effective_time_zone: Option<String>,
        effective_local_boundary: Option<String>,
        generation_source: String,
        content_markdown: String,
        created_at: String,
        updated_at: String,
    }

    #[derive(Debug, sqlx::FromRow)]
    struct BriefMembershipRow {
        brief_id: String,
        release_id: i64,
    }

    let rows = sqlx::query_as::<_, BriefRow>(
        r#"
        SELECT
          id,
          date,
          window_start_utc,
          window_end_utc,
          effective_time_zone,
          effective_local_boundary,
          generation_source,
          content_markdown,
          created_at,
          updated_at
        FROM briefs
        WHERE user_id = ?
        ORDER BY COALESCE(window_end_utc, created_at) DESC, created_at DESC, id DESC
        "#,
    )
    .bind(&user_id)
    .fetch_all(&state.pool)
    .await
    .map_err(ApiError::internal)?;

    let mut release_ids_by_brief = HashMap::<String, Vec<String>>::new();
    if !rows.is_empty() {
        let membership_rows = sqlx::query_as::<_, BriefMembershipRow>(
            r#"
            SELECT m.brief_id, m.release_id
            FROM brief_release_memberships m
            JOIN briefs b ON b.id = m.brief_id
            WHERE b.user_id = ?
            ORDER BY m.brief_id ASC, m.ordinal ASC
            "#,
        )
        .bind(&user_id)
        .fetch_all(&state.pool)
        .await
        .map_err(ApiError::internal)?;
        for row in membership_rows {
            release_ids_by_brief
                .entry(row.brief_id)
                .or_default()
                .push(row.release_id.to_string());
        }
    }

    let mut markdown_release_ids_by_brief = HashMap::<String, Vec<String>>::new();
    let mut markdown_release_refs_by_brief = HashMap::<String, Vec<InternalReleaseRef>>::new();
    let mut all_markdown_release_refs = Vec::<InternalReleaseRef>::new();
    for row in &rows {
        if !brief_uses_markdown_release_fallback(&row.generation_source)
            || release_ids_by_brief.contains_key(&row.id)
        {
            continue;
        }
        let refs = extract_brief_release_refs(&row.content_markdown);
        if refs.is_empty() {
            continue;
        }
        all_markdown_release_refs.extend(refs.iter().cloned());
        markdown_release_refs_by_brief.insert(row.id.clone(), refs);
    }

    if !all_markdown_release_refs.is_empty() {
        let resolved_ids_by_ref =
            resolve_brief_release_refs_batched(&state.pool, &all_markdown_release_refs)
                .await
                .map_err(ApiError::internal)?;

        for (brief_id, refs) in markdown_release_refs_by_brief {
            let mut seen_release_ids = HashSet::<i64>::new();
            let release_ids = refs
                .into_iter()
                .filter_map(|reference| resolved_ids_by_ref.get(&reference).copied())
                .filter(|release_id| seen_release_ids.insert(*release_id))
                .map(|value| value.to_string())
                .collect::<Vec<_>>();
            if !release_ids.is_empty() {
                markdown_release_ids_by_brief.insert(brief_id, release_ids);
            }
        }
    }

    let items = rows
        .into_iter()
        .map(|r| {
            let release_ids = release_ids_by_brief
                .remove(&r.id)
                .or_else(|| markdown_release_ids_by_brief.remove(&r.id))
                .unwrap_or_default();
            BriefSummaryItem {
                id: r.id,
                date: r.date,
                window_start: r.window_start_utc,
                window_end: r.window_end_utc,
                effective_time_zone: r.effective_time_zone,
                effective_local_boundary: r.effective_local_boundary,
                release_count: release_ids.len(),
                release_ids,
                preview_markdown: brief_preview_markdown(&r.content_markdown),
                covers_repo_stars: brief_markdown_has_section(&r.content_markdown, "### 获星"),
                covers_followers: brief_markdown_has_section(&r.content_markdown, "### 关注"),
                created_at: r.created_at,
                updated_at: r.updated_at,
            }
        })
        .collect::<Vec<_>>();

    Ok(Json(items))
}

#[derive(Debug, Serialize, Clone, sqlx::FromRow)]
pub struct BriefDetailItem {
    id: String,
    date: String,
    window_start: Option<String>,
    window_end: Option<String>,
    effective_time_zone: Option<String>,
    effective_local_boundary: Option<String>,
    release_count: usize,
    release_ids: Vec<String>,
    preview_markdown: String,
    covers_repo_stars: bool,
    covers_followers: bool,
    content_markdown: String,
    created_at: String,
    updated_at: String,
}

pub async fn get_brief(
    State(state): State<Arc<AppState>>,
    session: Session,
    headers: HeaderMap,
    Path(brief_id): Path<String>,
) -> Result<Json<BriefDetailItem>, ApiError> {
    let user_id = require_business_user_id(state.as_ref(), &session, &headers).await?;

    #[derive(Debug, sqlx::FromRow)]
    struct BriefRow {
        id: String,
        date: String,
        window_start_utc: Option<String>,
        window_end_utc: Option<String>,
        effective_time_zone: Option<String>,
        effective_local_boundary: Option<String>,
        generation_source: String,
        content_markdown: String,
        created_at: String,
        updated_at: String,
    }

    let row = sqlx::query_as::<_, BriefRow>(
        r#"
        SELECT
          id,
          date,
          window_start_utc,
          window_end_utc,
          effective_time_zone,
          effective_local_boundary,
          generation_source,
          content_markdown,
          created_at,
          updated_at
        FROM briefs
        WHERE user_id = ? AND id = ?
        "#,
    )
    .bind(&user_id)
    .bind(&brief_id)
    .fetch_optional(&state.pool)
    .await
    .map_err(ApiError::internal)?
    .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not_found", "brief not found"))?;

    let mut release_ids = sqlx::query_scalar::<_, i64>(
        r#"
        SELECT m.release_id
        FROM brief_release_memberships m
        WHERE m.brief_id = ?
        ORDER BY m.ordinal ASC
        "#,
    )
    .bind(&row.id)
    .fetch_all(&state.pool)
    .await
    .map_err(ApiError::internal)?
    .into_iter()
    .map(|value| value.to_string())
    .collect::<Vec<_>>();

    if release_ids.is_empty() && brief_uses_markdown_release_fallback(&row.generation_source) {
        let refs = extract_brief_release_refs(&row.content_markdown);
        if !refs.is_empty() {
            let resolved_ids_by_ref = resolve_brief_release_refs_batched(&state.pool, &refs)
                .await
                .map_err(ApiError::internal)?;
            let mut seen_release_ids = HashSet::<i64>::new();
            release_ids = refs
                .into_iter()
                .filter_map(|reference| resolved_ids_by_ref.get(&reference).copied())
                .filter(|release_id| seen_release_ids.insert(*release_id))
                .map(|value| value.to_string())
                .collect::<Vec<_>>();
        }
    }

    let preview_markdown = brief_preview_markdown(&row.content_markdown);
    let covers_repo_stars = brief_markdown_has_section(&row.content_markdown, "### 获星");
    let covers_followers = brief_markdown_has_section(&row.content_markdown, "### 关注");

    Ok(Json(BriefDetailItem {
        id: row.id,
        date: row.date,
        window_start: row.window_start_utc,
        window_end: row.window_end_utc,
        effective_time_zone: row.effective_time_zone,
        effective_local_boundary: row.effective_local_boundary,
        release_count: release_ids.len(),
        release_ids,
        preview_markdown,
        covers_repo_stars,
        covers_followers,
        content_markdown: row.content_markdown,
        created_at: row.created_at,
        updated_at: row.updated_at,
    }))
}

