#[derive(Debug)]
struct ReleaseSmartAiResult {
    value: Option<(Option<String>, Option<String>)>,
    call_ids: Vec<String>,
}

async fn request_release_smart_diagnostic(
    state: &AppState,
    system_prompt: &str,
    user_prompt: &str,
    max_tokens: u32,
    stage: &str,
    relation_role: &str,
    call_ids: &mut Vec<String>,
) -> Result<ai::ChatCompletionDiagnostic, ApiError> {
    let request = async {
        ai::chat_completion_with_diagnostics(state, system_prompt, user_prompt, max_tokens).await
    };
    let result = if let Some(mut context) = ai::current_llm_call_context() {
        context.source = format!("{}.stage.{stage}.role.{relation_role}", context.source);
        ai::with_llm_call_context(context, request).await
    } else {
        request.await
    };
    match result {
        Ok(diagnostic) => {
            if let Some(call_id) = diagnostic.call_id.clone() {
                call_ids.push(call_id);
            }
            Ok(diagnostic)
        }
        Err(err) => {
            if let Some(call_id) = ai::llm_call_id(&err) {
                call_ids.push(call_id);
            }
            Err(ApiError::from_llm_error(err))
        }
    }
}

async fn request_release_smart_payload(
    state: &AppState,
    system_prompt: &str,
    user_prompt: &str,
    stage: &str,
) -> std::result::Result<(ReleaseSmartSummaryPayload, Vec<String>), (ApiError, Vec<String>)> {
    let mut call_ids = Vec::new();
    let mut diagnostic = match request_release_smart_diagnostic(
        state,
        system_prompt,
        user_prompt,
        1024,
        stage,
        "primary",
        &mut call_ids,
    )
    .await
    {
        Ok(value) => value,
        Err(error) => return Err((error, call_ids)),
    };
    if diagnostic.finish_reason.as_deref() == Some("length") {
        diagnostic = match request_release_smart_diagnostic(
            state,
            system_prompt,
            user_prompt,
            1536,
            stage,
            "length_recovery",
            &mut call_ids,
        )
        .await
        {
            Ok(value) => value,
            Err(error) => return Err((error, call_ids)),
        };
    }
    if let Some(parsed) = parse_release_smart_summary_payload(&diagnostic.content) {
        return Ok((parsed, call_ids));
    }

    let repair_prompt = format!(
        "修复下列模型输出，使其严格符合 JSON 契约 {{\"valuable\":boolean,\"title_zh\":string|null,\"summary_bullets\":string[]}}。只返回 JSON，不要解释。\n\n原始输出：\n{}",
        diagnostic.content
    );
    let repaired = match request_release_smart_diagnostic(
        state,
        "你是 JSON 输出契约修复器。保留原始语义，不新增事实。",
        repair_prompt.as_str(),
        512,
        stage,
        "schema_repair",
        &mut call_ids,
    )
    .await
    {
        Ok(value) => value,
        Err(err) => return Err((err, call_ids)),
    };
    parse_release_smart_summary_payload(&repaired.content)
        .map(|parsed| (parsed, call_ids.clone()))
        .ok_or_else(|| {
            (
                ApiError::new(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "output_contract_invalid",
                    "AI output did not satisfy the JSON contract",
                ),
                call_ids,
            )
        })
}

async fn summarize_release_smart_candidate_with_ai_diagnostics(
    state: &AppState,
    user_id: &str,
    item: &ReleaseSmartBatchCandidate,
) -> std::result::Result<ReleaseSmartAiResult, (ApiError, Vec<String>)> {
    let body_prompt = release_smart_body_prompt(item);
    let (parsed, mut call_ids) = request_release_smart_payload(
        state,
        release_smart_body_system_prompt(),
        body_prompt.as_str(),
        "release_smart_body",
    )
    .await?;
    if parsed.valuable {
        let summary = render_smart_summary_markdown(&parsed.summary_bullets).ok_or_else(|| {
            (
                ApiError::new(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "output_contract_invalid",
                    "AI output did not contain usable summary bullets",
                ),
                call_ids.clone(),
            )
        })?;
        return Ok(ReleaseSmartAiResult {
            value: Some((parsed.title_zh, Some(summary))),
            call_ids,
        });
    }

    let Some(previous_tag_name) = item
        .previous_tag_name
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Ok(ReleaseSmartAiResult {
            value: None,
            call_ids,
        });
    };
    let compare_range = format!("{previous_tag_name}...{}", item.tag_name);
    let digest = fetch_release_compare_digest(
        state,
        user_id,
        item.full_name.as_str(),
        previous_tag_name,
        item.tag_name.as_str(),
    )
    .await
    .map_err(|error| (error, call_ids.clone()))?;
    let Some(digest) = digest else {
        return Ok(ReleaseSmartAiResult {
            value: None,
            call_ids,
        });
    };

    let diff_prompt = release_smart_diff_prompt(item, &compare_range, &digest);
    let (parsed, diff_call_ids) = request_release_smart_payload(
        state,
        release_smart_diff_system_prompt(),
        diff_prompt.as_str(),
        "release_smart_diff",
    )
    .await?;
    call_ids.extend(diff_call_ids);
    if !parsed.valuable {
        return Ok(ReleaseSmartAiResult {
            value: None,
            call_ids,
        });
    }
    let summary = render_smart_summary_markdown(&parsed.summary_bullets).ok_or_else(|| {
        (
            ApiError::new(
                StatusCode::INTERNAL_SERVER_ERROR,
                "output_contract_invalid",
                "AI output did not contain usable summary bullets",
            ),
            call_ids.clone(),
        )
    })?;
    Ok(ReleaseSmartAiResult {
        value: Some((parsed.title_zh, Some(summary))),
        call_ids,
    })
}

async fn prepare_release_smart_batch(
    state: &AppState,
    user_id: &str,
    release_ids: &[i64],
) -> Result<PreparedReleaseSmartBatch, ApiError> {
    if state.config.ai.is_none() {
        return Ok(PreparedReleaseSmartBatch {
            candidates: Vec::new(),
            pending: Vec::new(),
            smart: HashMap::new(),
            smart_call_ids: HashMap::new(),
            terminal: HashMap::new(),
            missing: HashSet::new(),
        });
    }

    let mut source_query = sqlx::QueryBuilder::<sqlx::Sqlite>::new(
        r#"
        WITH target_releases AS (
          SELECT
            r.repo_id AS repo_id,
            r.release_id AS release_id,
            r.tag_name AS tag_name,
            r.name AS name,
            r.body AS body,
            COALESCE(r.published_at, r.created_at, r.updated_at) AS sort_ts
          FROM repo_releases r
          WHERE r.release_id IN (
        "#,
    );
    {
        let mut separated = source_query.separated(", ");
        for release_id in release_ids {
            separated.push_bind(release_id);
        }
    }
    source_query.push(
        r#"
          )
        )
        SELECT
          tr.release_id AS release_id,
          sr.full_name AS full_name,
          tr.tag_name AS tag_name,
          tr.name AS name,
          tr.body AS body,
          (
            SELECT prev.tag_name
            FROM repo_releases prev
            WHERE prev.repo_id = tr.repo_id
              AND (
                COALESCE(prev.published_at, prev.created_at, prev.updated_at) < tr.sort_ts
                OR (
                  COALESCE(prev.published_at, prev.created_at, prev.updated_at) = tr.sort_ts
                  AND prev.release_id < tr.release_id
                )
              )
            ORDER BY
              COALESCE(prev.published_at, prev.created_at, prev.updated_at) DESC,
              prev.release_id DESC
            LIMIT 1
          ) AS previous_tag_name
        FROM target_releases tr
        JOIN user_release_visible_repos sr
          ON sr.user_id =
        "#,
    );
    source_query.push_bind(user_id);
    source_query.push(" AND sr.repo_id = tr.repo_id");

    let source_rows = source_query
        .build_query_as::<ReleaseSmartBatchSourceRow>()
        .fetch_all(&state.pool)
        .await
        .map_err(ApiError::internal)?;

    let mut source_by_id = HashMap::new();
    for row in source_rows {
        source_by_id.insert(row.release_id, row);
    }

    let mut candidates = Vec::new();
    let mut missing = HashSet::new();
    for release_id in release_ids {
        let Some(row) = source_by_id.get(release_id) else {
            missing.insert(*release_id);
            continue;
        };
        let entity_id = release_id.to_string();
        let title = row
            .name
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or(&row.tag_name)
            .to_owned();
        let body = release_feed_body(row.body.as_deref()).unwrap_or_default();
        let source_hash = crate::translations::release_smart_feed_source_hash(
            entity_id.as_str(),
            row.full_name.as_str(),
            title.as_str(),
            Some(body.as_str()),
            row.tag_name.as_str(),
            row.previous_tag_name.as_deref(),
        );
        candidates.push(ReleaseSmartBatchCandidate {
            release_id: *release_id,
            entity_id,
            full_name: row.full_name.clone(),
            tag_name: row.tag_name.clone(),
            previous_tag_name: row.previous_tag_name.clone(),
            title,
            body,
            source_hash,
        });
    }

    let mut cache_by_entity = HashMap::<String, TranslationCacheRow>::new();
    if !candidates.is_empty() {
        let mut cache_query = sqlx::QueryBuilder::<sqlx::Sqlite>::new(
            r#"
            SELECT entity_id, source_hash, status, title, summary, error_text
            FROM ai_translations
            WHERE user_id = "#,
        );
        cache_query.push_bind(user_id);
        cache_query.push(" AND entity_type = 'release_smart' AND lang = 'zh-CN' AND status IN ('ready', 'disabled', 'missing', 'error') AND entity_id IN (");
        {
            let mut separated = cache_query.separated(", ");
            for item in &candidates {
                separated.push_bind(&item.entity_id);
            }
        }
        cache_query.push(")");

        let cache_rows = cache_query
            .build_query_as::<TranslationCacheRow>()
            .fetch_all(&state.pool)
            .await
            .map_err(ApiError::internal)?;
        for row in cache_rows {
            cache_by_entity.insert(row.entity_id.clone(), row);
        }
    }

    let mut pending = Vec::new();
    let mut smart = HashMap::<i64, (Option<String>, Option<String>)>::new();
    let smart_call_ids = HashMap::<i64, Vec<String>>::new();
    let mut terminal = HashMap::<i64, ReleaseBatchTerminalState>::new();

    for item in &candidates {
        if let Some(cache) = cache_by_entity.get(&item.entity_id)
            && cache.source_hash == item.source_hash
        {
            if cache.status == "disabled"
                || (cache.status == "missing"
                    && cache.error_text.as_deref() == Some(SMART_NO_VALUABLE_VERSION_INFO))
            {
                terminal.insert(
                    item.release_id,
                    ReleaseBatchTerminalState {
                        status: cache.status.clone(),
                        error: cache.error_text.clone(),
                        failure_class: None,
                    },
                );
                continue;
            }
            if cache.status == "error" {
                terminal.insert(
                    item.release_id,
                    ReleaseBatchTerminalState {
                        status: cache.status.clone(),
                        error: cache.error_text.clone(),
                        failure_class: None,
                    },
                );
                continue;
            }
            if cache.status == "ready" {
                let ready = smart_ready_item(cache.title.clone(), cache.summary.clone(), None);
                if let Some(ready) = ready {
                    smart.insert(item.release_id, (ready.title, ready.summary));
                    continue;
                }
            }
        }
        pending.push(item.clone());
    }

    Ok(PreparedReleaseSmartBatch {
        candidates,
        pending,
        smart,
        smart_call_ids,
        terminal,
        missing,
    })
}

async fn mark_release_smart_requested(
    state: &AppState,
    user_id: &str,
    requested_at: &str,
    candidates: &[ReleaseSmartBatchCandidate],
) -> Result<(), ApiError> {
    for item in candidates {
        mark_translation_requested(
            state,
            user_id,
            requested_at,
            TranslationUpsert {
                entity_type: "release_smart",
                entity_id: &item.entity_id,
                lang: "zh-CN",
                source_hash: &item.source_hash,
                title: None,
                summary: None,
            },
        )
        .await?;
    }
    Ok(())
}

async fn upsert_release_smart_results(
    state: &AppState,
    user_id: &str,
    requested_at: &str,
    candidates: &[ReleaseSmartBatchCandidate],
    smart: &HashMap<i64, (Option<String>, Option<String>)>,
) -> Result<(), ApiError> {
    for item in candidates {
        if let Some((title, summary)) = smart.get(&item.release_id) {
            upsert_translation(
                state,
                user_id,
                requested_at,
                TranslationUpsert {
                    entity_type: "release_smart",
                    entity_id: &item.entity_id,
                    lang: "zh-CN",
                    source_hash: &item.source_hash,
                    title: title.as_deref(),
                    summary: summary.as_deref(),
                },
            )
            .await?;
        }
    }
    Ok(())
}

async fn upsert_release_smart_terminal_states(
    state: &AppState,
    user_id: &str,
    requested_at: &str,
    candidates: &[ReleaseSmartBatchCandidate],
    terminal: &HashMap<i64, ReleaseBatchTerminalState>,
) -> Result<(), ApiError> {
    for item in candidates {
        let Some(terminal_state) = terminal.get(&item.release_id) else {
            continue;
        };
        if terminal_state.status == "error" {
            // Technical failures remain on the work item for scheduler recovery;
            // do not turn them into a reusable cache hit.
            continue;
        }
        upsert_translation_terminal_status(
            state,
            user_id,
            requested_at,
            TranslationUpsert {
                entity_type: "release_smart",
                entity_id: &item.entity_id,
                lang: "zh-CN",
                source_hash: &item.source_hash,
                title: None,
                summary: None,
            },
            terminal_state.status.as_str(),
            terminal_state.error.as_deref(),
        )
        .await?;
    }
    Ok(())
}

fn build_release_smart_batch_item(
    release_id: i64,
    missing: &HashSet<i64>,
    terminal: &HashMap<i64, ReleaseBatchTerminalState>,
    smart: &HashMap<i64, (Option<String>, Option<String>)>,
) -> TranslateBatchItem {
    if missing.contains(&release_id) {
        return TranslateBatchItem {
            id: release_id.to_string(),
            lang: "zh-CN".to_owned(),
            status: "missing".to_owned(),
            title: None,
            summary: None,
            error: Some("release not found".to_owned()),
            failure_class: None,
        };
    }

    if let Some(terminal_state) = terminal.get(&release_id) {
        return TranslateBatchItem {
            id: release_id.to_string(),
            lang: "zh-CN".to_owned(),
            status: terminal_state.status.clone(),
            title: None,
            summary: None,
            error: terminal_state.error.clone().or_else(|| {
                (terminal_state.status == "missing")
                    .then_some("translation result missing".to_owned())
            }),
            failure_class: terminal_state.failure_class.clone(),
        };
    }

    if let Some((title, summary)) = smart.get(&release_id) {
        return TranslateBatchItem {
            id: release_id.to_string(),
            lang: "zh-CN".to_owned(),
            status: "ready".to_owned(),
            title: title.clone(),
            summary: summary.clone(),
            error: None,
            failure_class: None,
        };
    }

    TranslateBatchItem {
        id: release_id.to_string(),
        lang: "zh-CN".to_owned(),
        status: "error".to_owned(),
        title: None,
        summary: None,
        error: Some("release smart summary failed".to_owned()),
        failure_class: None,
    }
}

async fn summarize_releases_smart_batch_internal_with_diagnostics_and_work_items(
    state: &AppState,
    user_id: &str,
    release_ids: &[i64],
    work_item_ids: Option<&HashMap<i64, String>>,
) -> Result<(Vec<TranslateBatchItem>, HashMap<i64, Vec<String>>), ApiError> {
    if state.config.ai.is_none() {
        return Ok((
            release_ids
                .iter()
                .map(|release_id| TranslateBatchItem {
                    id: release_id.to_string(),
                    lang: "zh-CN".to_owned(),
                    status: "disabled".to_owned(),
                    title: None,
                    summary: None,
                    error: None,
                    failure_class: None,
                })
                .collect(),
            HashMap::new(),
        ));
    }

    let requested_at = chrono::Utc::now().to_rfc3339();
    let mut prepared = prepare_release_smart_batch(state, user_id, release_ids).await?;
    mark_release_smart_requested(state, user_id, requested_at.as_str(), &prepared.pending).await?;

    for item in &prepared.pending {
        let ai_result = if let Some(mut context) = ai::current_llm_call_context() {
            let relation_id = work_item_ids
                .and_then(|ids| ids.get(&item.release_id))
                .map(String::as_str)
                .unwrap_or(item.entity_id.as_str());
            context.source = format!("{}.work_item.{relation_id}", context.source);
            ai::with_llm_call_context(
                context,
                summarize_release_smart_candidate_with_ai_diagnostics(state, user_id, item),
            )
            .await
        } else {
            summarize_release_smart_candidate_with_ai_diagnostics(state, user_id, item).await
        };
        match ai_result {
            Ok(result) => {
                if let Some(value) = result.value {
                    prepared.smart.insert(item.release_id, value);
                } else {
                    prepared.terminal.insert(
                        item.release_id,
                        ReleaseBatchTerminalState {
                            status: "missing".to_owned(),
                            error: Some(SMART_NO_VALUABLE_VERSION_INFO.to_owned()),
                            failure_class: None,
                        },
                    );
                }
                prepared
                    .smart_call_ids
                    .insert(item.release_id, result.call_ids);
            }
            Err((err, call_ids)) => {
                prepared.smart_call_ids.insert(item.release_id, call_ids);
                prepared.terminal.insert(
                    item.release_id,
                    ReleaseBatchTerminalState {
                        status: "error".to_owned(),
                        error: Some(err.to_string()),
                        failure_class: err.failure_class().map(str::to_owned),
                    },
                );
            }
        }
    }

    upsert_release_smart_results(
        state,
        user_id,
        requested_at.as_str(),
        &prepared.candidates,
        &prepared.smart,
    )
    .await?;
    upsert_release_smart_terminal_states(
        state,
        user_id,
        requested_at.as_str(),
        &prepared.candidates,
        &prepared.terminal,
    )
    .await?;

    Ok((
        release_ids
            .iter()
            .map(|release_id| {
                build_release_smart_batch_item(
                    *release_id,
                    &prepared.missing,
                    &prepared.terminal,
                    &prepared.smart,
                )
            })
            .collect(),
        prepared.smart_call_ids,
    ))
}

#[allow(dead_code)]
pub(crate) async fn summarize_releases_smart_batch_internal_with_diagnostics(
    state: &AppState,
    user_id: &str,
    release_ids: &[i64],
) -> Result<(Vec<TranslateBatchItem>, HashMap<i64, Vec<String>>), ApiError> {
    translations::enqueue_release_smart_translation_requests(state, user_id, release_ids).await?;
    let response =
        read_release_smart_translation_batch_for_user(state, user_id, release_ids).await?;
    Ok((response.items, HashMap::new()))
}

pub(crate) async fn summarize_releases_smart_batch_for_scheduler(
    state: &AppState,
    user_id: &str,
    work_items: &[(i64, String)],
) -> Result<Vec<TranslateBatchItem>, ApiError> {
    let release_ids = work_items
        .iter()
        .map(|(release_id, _)| *release_id)
        .collect::<Vec<_>>();
    let work_item_ids = work_items
        .iter()
        .map(|(release_id, work_item_id)| (*release_id, work_item_id.clone()))
        .collect::<HashMap<_, _>>();
    Ok(
        summarize_releases_smart_batch_internal_with_diagnostics_and_work_items(
            state,
            user_id,
            &release_ids,
            Some(&work_item_ids),
        )
        .await?
        .0,
    )
}

#[allow(dead_code)]
pub(crate) async fn summarize_releases_smart_batch_internal(
    state: &AppState,
    user_id: &str,
    release_ids: &[i64],
) -> Result<Vec<TranslateBatchItem>, ApiError> {
    Ok(
        summarize_releases_smart_batch_internal_with_diagnostics(state, user_id, release_ids)
            .await?
            .0,
    )
}

#[allow(dead_code)]
pub async fn summarize_releases_smart_batch_for_user(
    state: &AppState,
    user_id: &str,
    release_ids: &[i64],
) -> Result<TranslateBatchResponse, ApiError> {
    let items = summarize_releases_smart_batch_internal(state, user_id, release_ids).await?;
    Ok(TranslateBatchResponse { items })
}

#[derive(Debug, sqlx::FromRow)]
struct ReleaseSmartTranslationCacheRow {
    entity_id: String,
    source_hash: String,
    status: String,
    title: Option<String>,
    summary: Option<String>,
    error_text: Option<String>,
    updated_at: String,
}

#[derive(Debug, sqlx::FromRow)]
struct ReleaseSmartWorkItemStateRow {
    entity_id: String,
    source_hash: String,
    status: String,
    result_status: Option<String>,
    error_text: Option<String>,
    updated_at: String,
}

pub(crate) async fn read_release_smart_translation_batch_for_user(
    state: &AppState,
    user_id: &str,
    release_ids: &[i64],
) -> Result<TranslateBatchResponse, ApiError> {
    if release_ids.is_empty() {
        return Ok(TranslateBatchResponse { items: Vec::new() });
    }
    let mut query = sqlx::QueryBuilder::<sqlx::Sqlite>::new(
        "SELECT entity_id, source_hash, status, title, summary, error_text, updated_at FROM ai_translations WHERE user_id = ",
    );
    query.push_bind(user_id);
    query.push(" AND entity_type = 'release_smart' AND lang = 'zh-CN' AND entity_id IN (");
    {
        let mut separated = query.separated(", ");
        for release_id in release_ids {
            separated.push_bind(release_id.to_string());
        }
    }
    query.push(")");
    let rows = query
        .build_query_as::<ReleaseSmartTranslationCacheRow>()
        .fetch_all(&state.pool)
        .await
        .map_err(ApiError::internal)?;
    let by_entity = rows
        .into_iter()
        .map(|row| (row.entity_id.clone(), row))
        .collect::<HashMap<_, _>>();
    let mut work_item_query = sqlx::QueryBuilder::<sqlx::Sqlite>::new(
        "SELECT entity_id, source_hash, status, result_status, error_text, updated_at FROM translation_work_items WHERE scope_user_id = ",
    );
    work_item_query.push_bind(user_id);
    work_item_query
        .push(" AND kind = 'release_smart' AND variant = 'feed_card' AND entity_id IN (");
    {
        let mut separated = work_item_query.separated(", ");
        for release_id in release_ids {
            separated.push_bind(release_id.to_string());
        }
    }
    work_item_query.push(") ORDER BY updated_at DESC, id DESC");
    let work_item_rows = work_item_query
        .build_query_as::<ReleaseSmartWorkItemStateRow>()
        .fetch_all(&state.pool)
        .await
        .map_err(ApiError::internal)?;
    let latest_work_items = work_item_rows.into_iter().fold(
        HashMap::<String, ReleaseSmartWorkItemStateRow>::new(),
        |mut map, row| {
            map.entry(row.entity_id.clone()).or_insert(row);
            map
        },
    );
    let items = release_ids
        .iter()
        .map(|release_id| {
            let id = release_id.to_string();
            let cache = by_entity.get(&id);
            if let Some(work_item) = latest_work_items.get(&id) {
                let cache_is_newer =
                    cache.is_some_and(|row| row.updated_at >= work_item.updated_at);
                let cache_matches_work =
                    cache.is_some_and(|row| row.source_hash == work_item.source_hash);
                if !cache_is_newer || cache_matches_work {
                    if matches!(work_item.status.as_str(), "queued" | "running") {
                        return TranslateBatchItem {
                            id,
                            lang: "zh-CN".to_owned(),
                            status: "processing".to_owned(),
                            title: None,
                            summary: None,
                            error: None,
                            failure_class: None,
                        };
                    }
                    if work_item.result_status.as_deref() == Some("error") {
                        let classified = translations::classify_translation_error(
                            work_item.error_text.as_deref(),
                        );
                        return TranslateBatchItem {
                            id,
                            lang: "zh-CN".to_owned(),
                            status: "error".to_owned(),
                            title: None,
                            summary: None,
                            error: classified.map(|value| value.summary.to_owned()),
                            failure_class: None,
                        };
                    }
                    if work_item.result_status.as_deref() == Some("missing") {
                        return TranslateBatchItem {
                            id,
                            lang: "zh-CN".to_owned(),
                            status: "missing".to_owned(),
                            title: None,
                            summary: None,
                            error: None,
                            failure_class: None,
                        };
                    }
                }
            }
            let Some(row) = cache else {
                return TranslateBatchItem {
                    id,
                    lang: "zh-CN".to_owned(),
                    status: "processing".to_owned(),
                    title: None,
                    summary: None,
                    error: None,
                    failure_class: None,
                };
            };
            let classified = translations::classify_translation_error(row.error_text.as_deref());
            TranslateBatchItem {
                id,
                lang: "zh-CN".to_owned(),
                status: row.status.clone(),
                title: row.title.clone(),
                summary: row.summary.clone(),
                error: classified.map(|value| value.summary.to_owned()),
                failure_class: None,
            }
        })
        .collect();
    Ok(TranslateBatchResponse { items })
}

#[allow(dead_code)]
async fn translate_releases_batch_stream_worker(
    state: Arc<AppState>,
    user_id: String,
    release_ids: Vec<i64>,
    task_id: String,
    tx: mpsc::Sender<Result<Bytes, Infallible>>,
) {
    let heartbeat = jobs::spawn_task_lease_heartbeat(state.clone(), task_id.clone());
    let mut ready_count = 0usize;
    let mut disabled_count = 0usize;
    let mut missing_count = 0usize;
    let mut error_count = 0usize;

    let context = ai::LlmCallContext {
        source: "api.translate_releases_batch_stream".to_owned(),
        requested_by: Some(user_id.clone()),
        parent_task_id: Some(task_id.clone()),
        parent_task_type: Some(jobs::TASK_TRANSLATE_RELEASE_BATCH.to_owned()),
        parent_translation_batch_id: None,
        parent_brief_id: None,
    };

    let result = ai::with_llm_call_context(context, async {
        jobs::append_task_event(
            state.as_ref(),
            task_id.as_str(),
            "task.progress",
            json!({
                "task_id": task_id.as_str(),
                "stage": "collect",
                "total_releases": release_ids.len(),
            }),
        )
        .await
        .map_err(ApiError::internal)?;

        if state.config.ai.is_none() {
            for release_id in &release_ids {
                let item = TranslateBatchItem {
                    id: release_id.to_string(),
                    lang: "zh-CN".to_owned(),
                    status: "disabled".to_owned(),
                    title: None,
                    summary: None,
                    error: None,
                    failure_class: None,
                };
                if !send_batch_stream_event(
                    &tx,
                    TranslateBatchStreamEvent {
                        event: "item",
                        item: Some(item.clone()),
                        error: None,
                    },
                )
                .await
                {
                    return Err(ApiError::internal("stream client disconnected"));
                }

                accumulate_batch_item_stats(
                    &item,
                    &mut ready_count,
                    &mut disabled_count,
                    &mut missing_count,
                    &mut error_count,
                );
                jobs::append_task_event(
                    state.as_ref(),
                    task_id.as_str(),
                    "task.progress",
                    json!({
                        "task_id": task_id.as_str(),
                        "stage": "release",
                        "release_id": item.id,
                        "item_status": item.status,
                        "item_error": item.error.clone(),
                    }),
                )
                .await
                .map_err(ApiError::internal)?;
            }
            if !send_batch_stream_event(
                &tx,
                TranslateBatchStreamEvent {
                    event: "done",
                    item: None,
                    error: None,
                },
            )
            .await
            {
                return Err(ApiError::internal("stream client disconnected"));
            }
            return Ok(());
        }

        let mut prepared = prepare_release_batch(state.as_ref(), &user_id, &release_ids).await?;
        let detail_pending_ids = prepared
            .detail_pending_candidates
            .iter()
            .map(|candidate| candidate.release_id)
            .collect::<HashSet<_>>();

        for release_id in &release_ids {
            if detail_pending_ids.contains(release_id) {
                continue;
            }
            let item = build_release_batch_item(
                *release_id,
                &prepared.missing,
                &prepared.terminal,
                &prepared.translated,
            );
            if !send_batch_stream_event(
                &tx,
                TranslateBatchStreamEvent {
                    event: "item",
                    item: Some(item.clone()),
                    error: None,
                },
            )
            .await
            {
                return Err(ApiError::internal("stream client disconnected"));
            }

            accumulate_batch_item_stats(
                &item,
                &mut ready_count,
                &mut disabled_count,
                &mut missing_count,
                &mut error_count,
            );
            jobs::append_task_event(
                state.as_ref(),
                task_id.as_str(),
                "task.progress",
                json!({
                    "task_id": task_id.as_str(),
                    "stage": "release",
                    "release_id": item.id,
                    "item_status": item.status,
                    "item_error": item.error.clone(),
                }),
            )
            .await
            .map_err(ApiError::internal)?;
        }

        if !prepared.detail_pending_candidates.is_empty() {
            for candidate in &prepared.detail_pending_candidates {
                if !send_batch_stream_event(
                    &tx,
                    TranslateBatchStreamEvent {
                        event: "item",
                        item: Some(TranslateBatchItem {
                            id: candidate.release_id.to_string(),
                            lang: "zh-CN".to_owned(),
                            status: "processing".to_owned(),
                            title: None,
                            summary: None,
                            error: None,
                            failure_class: None,
                        }),
                        error: None,
                    },
                )
                .await
                {
                    return Err(ApiError::internal("stream client disconnected"));
                }
            }

            for item in translate_pending_release_batch_candidates(
                state.as_ref(),
                &user_id,
                &prepared.detail_pending_candidates,
            )
            .await?
            {
                if let Ok(release_id) = item.id.parse::<i64>() {
                    match item.status.as_str() {
                        "ready" => {
                            prepared
                                .translated
                                .insert(release_id, (item.title.clone(), item.summary.clone()));
                        }
                        "disabled" | "missing" | "error" => {
                            prepared.terminal.insert(
                                release_id,
                                ReleaseBatchTerminalState {
                                    status: item.status.clone(),
                                    error: item.error.clone(),
                                    failure_class: item.failure_class.clone(),
                                },
                            );
                        }
                        _ => {}
                    }
                }
                if !send_batch_stream_event(
                    &tx,
                    TranslateBatchStreamEvent {
                        event: "item",
                        item: Some(item.clone()),
                        error: None,
                    },
                )
                .await
                {
                    return Err(ApiError::internal("stream client disconnected"));
                }
                accumulate_batch_item_stats(
                    &item,
                    &mut ready_count,
                    &mut disabled_count,
                    &mut missing_count,
                    &mut error_count,
                );
                jobs::append_task_event(
                    state.as_ref(),
                    task_id.as_str(),
                    "task.progress",
                    json!({
                        "task_id": task_id.as_str(),
                        "stage": "release",
                        "release_id": item.id,
                        "item_status": item.status,
                        "item_error": item.error.clone(),
                    }),
                )
                .await
                .map_err(ApiError::internal)?;
            }
        }

        if !send_batch_stream_event(
            &tx,
            TranslateBatchStreamEvent {
                event: "done",
                item: None,
                error: None,
            },
        )
        .await
        {
            return Err(ApiError::internal("stream client disconnected"));
        }
        Ok::<(), ApiError>(())
    })
    .await;

    match result {
        Ok(()) => {
            let summary = json!({
                "total": release_ids.len(),
                "ready": ready_count,
                "disabled": disabled_count,
                "missing": missing_count,
                "error": error_count,
            });
            let _ = jobs::complete_task(
                state.as_ref(),
                task_id.as_str(),
                jobs::STATUS_SUCCEEDED,
                Some(summary.clone()),
                None,
            )
            .await;
            heartbeat.stop().await;
            let _ = jobs::append_task_event(
                state.as_ref(),
                task_id.as_str(),
                "task.completed",
                json!({
                    "task_id": task_id.as_str(),
                    "status": jobs::STATUS_SUCCEEDED,
                    "summary": summary,
                }),
            )
            .await;
        }
        Err(err) => {
            let error_message = format!("{}: stream worker failed", err.code());
            let _ = jobs::complete_task(
                state.as_ref(),
                task_id.as_str(),
                jobs::STATUS_FAILED,
                None,
                Some(error_message.clone()),
            )
            .await;
            let _ = jobs::append_task_event(
                state.as_ref(),
                task_id.as_str(),
                "task.completed",
                json!({
                    "task_id": task_id.as_str(),
                    "status": jobs::STATUS_FAILED,
                    "error": error_message,
                }),
            )
            .await;
            heartbeat.stop().await;
            let _ = send_batch_stream_event(
                &tx,
                TranslateBatchStreamEvent {
                    event: "error",
                    item: None,
                    error: Some(error_message),
                },
            )
            .await;
        }
    }
}

