    async fn seed_github_connection(
        pool: &SqlitePool,
        user_id: &str,
        github_user_id: i64,
        login: &str,
        linked_at: &str,
    ) {
        sqlx::query(
            r#"
            INSERT INTO github_connections (
              id,
              user_id,
              github_user_id,
              login,
              access_token_ciphertext,
              access_token_nonce,
              scopes,
              linked_at,
              updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            "#,
        )
        .bind(crate::local_id::generate_local_id())
        .bind(user_id)
        .bind(github_user_id)
        .bind(login)
        .bind(vec![0_u8])
        .bind(vec![0_u8])
        .bind("read:user")
        .bind(linked_at)
        .bind(linked_at)
        .execute(pool)
        .await
        .expect("seed github connection");
    }

