    async fn seed_access_refresh_task(
        pool: &SqlitePool,
        task_id: &str,
        requested_by: &str,
        status: &str,
    ) {
        let now = "2026-02-23T00:00:00Z";
        let started_at = match status {
            jobs::STATUS_RUNNING | jobs::STATUS_SUCCEEDED | jobs::STATUS_FAILED => Some(now),
            _ => None,
        };
        let finished_at = match status {
            jobs::STATUS_SUCCEEDED | jobs::STATUS_FAILED | jobs::STATUS_CANCELED => Some(now),
            _ => None,
        };
        sqlx::query(
            r#"
            INSERT INTO job_tasks (
              id,
              task_type,
              status,
              source,
              requested_by,
              parent_task_id,
              payload_json,
              result_json,
              error_message,
              cancel_requested,
              created_at,
              started_at,
              finished_at,
              updated_at
            )
            VALUES (?, ?, ?, 'tests', ?, NULL, '{}', NULL, NULL, 0, ?, ?, ?, ?)
            "#,
        )
        .bind(task_id)
        .bind(jobs::TASK_SYNC_ACCESS_REFRESH)
        .bind(status)
        .bind(requested_by)
        .bind(now)
        .bind(started_at)
        .bind(finished_at)
        .bind(now)
        .execute(pool)
        .await
        .expect("seed access refresh task");
    }

    async fn seed_admin_dashboard_task(
        pool: &SqlitePool,
        task_id: &str,
        task_type: &str,
        status: &str,
        requested_by: &str,
        created_at: &str,
    ) {
        let started_at = match status {
            jobs::STATUS_RUNNING | jobs::STATUS_SUCCEEDED | jobs::STATUS_FAILED => Some(created_at),
            _ => None,
        };
        let finished_at = match status {
            jobs::STATUS_SUCCEEDED | jobs::STATUS_FAILED | jobs::STATUS_CANCELED => {
                Some(created_at)
            }
            _ => None,
        };
        sqlx::query(
            r#"
            INSERT INTO job_tasks (
              id,
              task_type,
              status,
              source,
              requested_by,
              parent_task_id,
              payload_json,
              result_json,
              error_message,
              cancel_requested,
              created_at,
              started_at,
              finished_at,
              updated_at
            )
            VALUES (?, ?, ?, 'tests', ?, NULL, '{}', NULL, NULL, 0, ?, ?, ?, ?)
            "#,
        )
        .bind(task_id)
        .bind(task_type)
        .bind(status)
        .bind(requested_by)
        .bind(created_at)
        .bind(started_at)
        .bind(finished_at)
        .bind(created_at)
        .execute(pool)
        .await
        .expect("seed admin dashboard task");
    }

    async fn seed_llm_call(
        pool: &SqlitePool,
        call_id: &str,
        status: &str,
        source: &str,
        requested_by: Option<String>,
    ) {
        let now = chrono::Utc::now().to_rfc3339();
        seed_llm_call_with_created_at(pool, call_id, status, source, requested_by, &now).await;
    }

    async fn seed_llm_call_with_created_at(
        pool: &SqlitePool,
        call_id: &str,
        status: &str,
        source: &str,
        requested_by: Option<String>,
        created_at: &str,
    ) {
        let started_at = match status {
            "queued" => None,
            _ => Some(created_at),
        };
        let finished_at = match status {
            "queued" | "running" => None,
            _ => Some(created_at),
        };
        sqlx::query(
            r#"
            INSERT INTO llm_calls (
              id,
              status,
              source,
              model,
              requested_by,
              parent_task_id,
              parent_task_type,
              max_tokens,
              attempt_count,
              scheduler_wait_ms,
              first_token_wait_ms,
              duration_ms,
              input_tokens,
              output_tokens,
              cached_input_tokens,
              total_tokens,
              input_messages_json,
              output_messages_json,
              prompt_text,
              response_text,
              error_text,
              created_at,
              started_at,
              finished_at,
              updated_at
            )
            VALUES (?, ?, ?, 'gpt-4o-mini', ?, NULL, NULL, 900, 1, 120, 340, 800, 120, 55, 20, 175, '[{"role":"system","content":"s"},{"role":"user","content":"u"}]', '[{"role":"assistant","content":"ok"}]', 'prompt', 'ok', NULL, ?, ?, ?, ?)
            "#,
        )
        .bind(call_id)
        .bind(status)
        .bind(source)
        .bind(requested_by)
        .bind(created_at)
        .bind(started_at)
        .bind(finished_at)
        .bind(created_at)
        .execute(pool)
        .await
        .expect("seed llm call");
    }

