    #[tokio::test]
    async fn summarize_release_smart_candidate_with_ai_sends_specific_title_contract() {
        let pool = setup_pool().await;
        let calls = Arc::new(AtomicUsize::new(0));
        let calls_for_route = Arc::clone(&calls);
        let base_url = spawn_test_ai_server(Router::new().route(
            "/chat/completions",
            post(move |Json(payload): Json<Value>| {
                let calls_for_route = Arc::clone(&calls_for_route);
                async move {
                    calls_for_route.fetch_add(1, Ordering::SeqCst);
                    let system_prompt = payload["messages"][0]["content"]
                        .as_str()
                        .unwrap_or_default();
                    let user_prompt = payload["messages"][1]["content"]
                        .as_str()
                        .unwrap_or_default();

                    assert!(system_prompt.contains("标题必须具体且证据绑定"));
                    assert!(
                        system_prompt.contains(
                            "禁止输出“版本更新”“更新要点”“发布说明”“版本发布”这类空泛标题"
                        )
                    );
                    assert!(user_prompt.contains("坏标题：\"v2.42.0 版本更新\""));
                    assert!(user_prompt.contains("好标题：\"v2.42.0 新增对话操作标签页\""));
                    assert!(
                        user_prompt
                            .contains("好标题：\"v2.42.1 修复 Dashboard 持久化调用详情刷新\"")
                    );
                    assert!(
                        user_prompt
                            .contains("`Channel` / `Bump` / `Commit SHA` 只能辅助 summary_bullets")
                    );

                    let content = json!({
                        "valuable": true,
                        "title_zh": "v2.42.0 新增对话操作标签页",
                        "summary_bullets": [
                            "新增对话操作标签页，用于管理提示词缓存中的对话数据"
                        ]
                    })
                    .to_string();
                    let response = json!({
                        "choices": [{"message": {"content": content}}],
                        "usage": {"prompt_tokens": 10, "completion_tokens": 10, "total_tokens": 20}
                    });
                    (
                        StatusCode::OK,
                        [(header::CONTENT_TYPE, "application/json")],
                        Json(response),
                    )
                }
            }),
        ))
        .await;
        let state = setup_state_with_ai_base_url(pool, base_url);

        let summarized = summarize_release_smart_candidate_with_ai(
            state.as_ref(),
            "user-1",
            &ReleaseSmartBatchCandidate {
                release_id: 356108921,
                entity_id: "356108921".to_owned(),
                full_name: "IvanLi-CN/codex-vibe-monitor".to_owned(),
                tag_name: "v2.42.0".to_owned(),
                previous_tag_name: Some("v2.41.2".to_owned()),
                title: "v2.42.0".to_owned(),
                body: "PR: #653 feat(prompt-cache): add conversation operations tab\nChannel: stable\nBump: minor\nCommit: 60f036ff163d14a44d179101b8ebf4539a1473ee".to_owned(),
                source_hash: "hash".to_owned(),
            },
        )
        .await
        .expect("summarize release smart");

        assert_eq!(
            summarized,
            Some((
                Some("v2.42.0 新增对话操作标签页".to_owned()),
                Some("- 新增对话操作标签页，用于管理提示词缓存中的对话数据".to_owned()),
            ))
        );
        assert_eq!(calls.load(Ordering::SeqCst), 1);
    }

    #[test]
    fn build_compare_digest_filters_noise_and_keeps_meaningful_patch_excerpt() {
        let digest = build_compare_digest(&GitHubCompareResponse {
            status: Some("ahead".to_owned()),
            ahead_by: Some(2),
            behind_by: Some(0),
            total_commits: Some(2),
            commits: vec![
                GitHubCompareCommit {
                    sha: "abcdef123456".to_owned(),
                    commit: GitHubCompareCommitDetail {
                        message: "feat: add release smart fallback\n\nextra".to_owned(),
                    },
                },
                GitHubCompareCommit {
                    sha: "fedcba654321".to_owned(),
                    commit: GitHubCompareCommitDetail {
                        message: "fix: keep markdown bullets readable".to_owned(),
                    },
                },
            ],
            files: vec![
                GitHubCompareFile {
                    filename: "web/bun.lock".to_owned(),
                    status: Some("modified".to_owned()),
                    additions: Some(10),
                    deletions: Some(2),
                    changes: Some(12),
                    patch: Some("+lockfileVersion: 1".to_owned()),
                },
                GitHubCompareFile {
                    filename: "src/api.rs".to_owned(),
                    status: Some("modified".to_owned()),
                    additions: Some(12),
                    deletions: Some(3),
                    changes: Some(15),
                    patch: Some(
                        "@@ -1,3 +1,6 @@\n-use old\n+use new\n context\n+let digest = build();\n-http://example.com\n+summary.push(\"ok\");\n".to_owned(),
                    ),
                },
                GitHubCompareFile {
                    filename: "dist/app.min.js".to_owned(),
                    status: Some("modified".to_owned()),
                    additions: Some(100),
                    deletions: Some(40),
                    changes: Some(140),
                    patch: Some("+compiled".to_owned()),
                },
            ],
        })
        .expect("compare digest");

        assert!(digest.contains("compare_status: ahead"));
        assert!(digest.contains("commit_subjects:"));
        assert!(digest.contains("feat: add release smart fallback"));
        assert!(digest.contains("changed_files:"));
        assert!(digest.contains("src/api.rs [modified]"));
        assert!(digest.contains("patch_excerpts:"));
        assert!(digest.contains("### src/api.rs"));
        assert!(!digest.contains("web/bun.lock"));
        assert!(!digest.contains("dist/app.min.js"));
    }

